(1, 'The New Gym Nguyễn Thị Minh Khai', 'the-new-gym-nguyen-thi-minh-khai-1', 'Phòng tập The New Gym Nguyễn Thị Minh Khai tại Quận 1 sở hữu không gian tập luyện chuyên nghiệp, trang bị máy tập cao cấp, không gian rộng rãi thoáng mát cùng nhiều tiện ích đẳng cấp.', 'Số 13 Đường The New Gym Nguyễn Thị Minh Khai, Quận 1', 1, NULL, NULL, +84281000001, 'contact.gym1@gymfinder.test', 'https://gym1.gymfinder.test', 250000, 500000, '05:30 - 21:30', 'https://images.unsplash.com/photo-1534438327276-14e5300c3a48?auto=format&fit=crop&w=800&q=80', 5.0, 2, 1, 'active'),
(2, 'California Centuryon Saigon Centre', 'california-centuryon-saigon-centre-2', 'Phòng tập California Centuryon Saigon Centre tại Quận 1 sở hữu không gian tập luyện chuyên nghiệp, trang bị máy tập cao cấp, không gian rộng rãi thoáng mát cùng nhiều tiện ích đẳng cấp.', 'Số 16 Đường California Centuryon Saigon Centre, Quận 1', 1, NULL, NULL, +84281000002, 'contact.gym2@gymfinder.test', 'https://gym2.gymfinder.test', 300000, 600000, '06:00 - 22:00', 'https://images.unsplash.com/photo-1571019614242-c5c5dee9f50b?auto=format&fit=crop&w=800&q=80', 5.0, 3, 1, 'active'),
(3, 'Fit Center Bến Thành', 'fit-center-ben-thanh-3', 'Phòng tập Fit Center Bến Thành tại Quận 1 sở hữu không gian tập luyện chuyên nghiệp, trang bị máy tập cao cấp, không gian rộng rãi thoáng mát cùng nhiều tiện ích đẳng cấp.', 'Số 19 Đường Fit Center Bến Thành, Quận 1', 1, NULL, NULL, +84281000003, 'contact.gym3@gymfinder.test', 'https://gym3.gymfinder.test', 500000, 1000000, '05:00 - 23:00', 'https://images.unsplash.com/photo-1540497077202-7c8a3999166f?auto=format&fit=crop&w=800&q=80', 4.3, 3, 0, 'active'),
(4, 'MMA Gym Fitness Cống Quỳnh', 'mma-gym-fitness-cong-quynh-4', 'Phòng tập MMA Gym Fitness Cống Quỳnh tại Quận 1 sở hữu không gian tập luyện chuyên nghiệp, trang bị máy tập cao cấp, không gian rộng rãi thoáng mát cùng nhiều tiện ích đẳng cấp.', 'Số 22 Đường MMA Gym Fitness Cống Quỳnh, Quận 1', 1, NULL, NULL, +84281000004, 'contact.gym4@gymfinder.test', 'https://gym4.gymfinder.test', 600000, 1200000, '06:00 - 22:00', 'https://images.unsplash.com/photo-1517838277536-f5f99be501cd?auto=format&fit=crop&w=800&q=80', 5.0, 1, 0, 'active'),
(5, 'Advance Fitness & Gym Hàm Nghi', 'advance-fitness-gym-ham-nghi-5', 'Phòng tập Advance Fitness & Gym Hàm Nghi tại Quận 1 sở hữu không gian tập luyện chuyên nghiệp, trang bị máy tập cao cấp, không gian rộng rãi thoáng mát cùng nhiều tiện ích đẳng cấp.', 'Số 25 Đường Advance Fitness & Gym Hàm Nghi, Quận 1', 1, NULL, NULL, +84281000005, 'contact.gym5@gymfinder.test', 'https://gym5.gymfinder.test', 700000, 1500000, '05:30 - 21:30', 'https://images.unsplash.com/photo-1584735935682-2f2b69dff9d2?auto=format&fit=crop&w=800&q=80', 4.3, 3, 0, 'active'),
