(2, 2, 'gym', 2, NULL, 5, 'Rất hài lòng với dịch vụ tại đây, nhân viên và HLV luôn niềm nở, hỗ trợ nhiệt tình.', 'approved', 1, '2026-09-02 10:00:00', NULL, '2026-09-02 10:00:00'),
