(4, 2, 'gym', 4, NULL, 5, 'Vừa đăng ký gói tập 3 tháng, ấn tượng ban đầu khá tốt, đang chờ theo dõi thêm.', 'pending', NULL, NULL, NULL, '2026-09-04 10:00:00'),
