(6, 2, 'gym', 6, NULL, 5, 'Đã tập ở đây được 6 tháng và thấy sức khỏe cải thiện rõ rệt, 10/10.', 'approved', 1, '2026-09-06 10:00:00', NULL, '2026-09-06 10:00:00'),
(7, 2, 'gym', 7, NULL, 5, 'Môi trường năng động, âm nhạc truyền cảm hứng, phòng tắm và xông hơi rất sạch.', 'approved', 1, '2026-08-07 10:00:00', NULL, '2026-08-07 10:00:00'),
